html:
{%- from "templates/print_formats/standard_macros.html" import add_header -%}
{{ add_header(0, 1, doc, letter_head, no_letterhead, footer, print_settings) }}
<style>
.al-doc { font-size: 11px; color: #1f2933; }
.al-doc h2 { font-size: 18px; margin: 0 0 2px; letter-spacing: .02em; }
.al-doc .al-sub { color: #52606d; margin-bottom: 12px; }
.al-doc table { width: 100%; border-collapse: collapse; margin: 8px 0 12px; }
.al-doc th { background: #f0f2f5; text-align: left; font-weight: 600; }
.al-doc th, .al-doc td { border: 1px solid #cbd2d9; padding: 4px 6px; vertical-align: top; }
.al-doc .al-grid td { border: none; padding: 2px 8px 2px 0; }
.al-doc .al-label { color: #52606d; width: 22%; }
.al-doc .num { text-align: right; white-space: nowrap; }
.al-doc .al-worse { font-weight: 700; text-decoration: underline; }
.al-doc .al-sign { margin-top: 36px; }
.al-doc .al-sign td { border: none; border-top: 1px solid #52606d; width: 25%; padding-top: 4px; text-align: center; }
.al-doc .al-note { border-left: 3px solid #9aa5b1; padding: 4px 8px; color: #3e4c59; margin: 8px 0; }
</style>
<div class="al-doc">
<h2>{{ _("Security Deposit Refund") if doc.al_deposit_type == "Deposit Refund" else _("Security Deposit Receipt") }}</h2>
<div class="al-sub">{{ doc.name }} &middot; {{ doc.get_formatted("posting_date") }}</div>
<table class="al-grid">
<tr><td class="al-label">{{ _("Customer") }}</td><td><b>{{ doc.party_name }}</b></td><td class="al-label">{{ _("Rental agreement") }}</td><td>{{ doc.al_rental_agreement or "" }}</td></tr>
<tr><td class="al-label">{{ _("Amount") }}</td><td><b>{{ doc.get_formatted("paid_amount") }}</b></td><td class="al-label">{{ _("Mode") }}</td><td>{{ doc.mode_of_payment or "" }}{% if doc.reference_no %} &middot; {{ doc.reference_no }} ({{ doc.get_formatted("reference_date") }}){% endif %}</td></tr>
</table>
<div>{{ _("Amount in words") }}: {{ doc.in_words or "" }}</div>
{% if doc.al_deposit_type != "Deposit Refund" %}
<div class="al-note">{{ _("This is a refundable security deposit held against the rental agreement above. It is not an advance against rent. It is refundable after the equipment is returned, less any approved damage recovery and any amount still due under the agreement.") }}</div>
{% else %}
<div class="al-note">{{ _("Refund of the security deposit held against the rental agreement above.") }}</div>
{% endif %}
{% if doc.remarks %}<div>{{ doc.remarks }}</div>{% endif %}
<table class="al-sign"><tr><td>{{ _("Received by") if doc.al_deposit_type != "Deposit Refund" else _("Paid by") }}</td><td></td><td></td><td>{{ _("Customer") }}</td></tr></table>
</div>
